 src=entry['source'].strip();path=rel(entry['source_file'])
 candidates=[s for s in owned if rel(s['source_file'])==path and s.get('source','').strip().endswith(src)]
 if not candidates and entry['function']=='extraction_profile::from_facts':
  candidates=[s for s in owned if rel(s['source_file'])==path and s.get('source','').split('{',1)[-1].strip()==src.split('{',1)[-1].strip()]
  adaptations.append({'function':entry['function'],'reason':'C93 adds generic body parameter to from_facts declaration only; exact captured/current body bytes equal. Captured declaration independently reviewed; no event or statement changed.'})
 assert len(candidates)==1,(entry['function'],len(candidates))
 captured=candidates[0]
 assert len(captured['active_functions'])==1,(entry['function'],captured['active_functions'])
 return dict(package='rstyle-pdg',target_kind='lib',function=captured['active_functions'][0],source_file=path,source=captured['source'],included=True,unsuppressed=True)
