  events=collections.Counter()
  if suffix=='a':
   for counts in f['events'].values():events.update(counts)
  else:
   for e in f['events']:events[e['kind']]+=e['count']
  events={k:v for k,v in events.items() if v}
  details=[]
  for d in f['details']:
   label=d['label']
   if suffix=='a':
    label=d['kind']+': '+label
    if d.get('via'):label+=' (via '+d['via']+')'
   details.append({'label':label,'count':d['count']})
  actual=f.get('expected_actual',f.get('expected_static_density_actual',f.get('actual')))
  labels['samples'].append({**source_entry,'propagation_reviewed':True,'propagation_inputs':helpers,'density':{'complete':True,'statements':f['statements'],'code_lines':f['code_lines'],'events':events,'details':details,'actual':actual,'outcome':'finding' if actual>500 else 'evaluated_no_finding','exempt':False}})
